def _yellow_edge_line_fraction(image: Image.Image, box: tuple[int, int, int, int],
                               *, horizontal: bool) -> float:
    part = image.crop(box)
    if part.width < 1 or part.height < 1:
        return 0.0
    pixels = part.load()
    if horizontal:
        return max(sum(_yellow(pixels[x, y]) for x in range(part.width)) / part.width
                   for y in range(part.height))
    return max(sum(_yellow(pixels[x, y]) for y in range(part.height)) / part.height
               for x in range(part.width))
